def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    offline_until = {}  # user_id -> time when they come back online

    for event in events:
        if event[0] == "OFFLINE":
            ts = int(event[1])
            uid = int(event[2])
            offline_until[uid] = ts + 60
        else:  # MESSAGE
