from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # offline_until[i] is the time when user i comes back online (i.e., offline until this time)
    # If offline_until[i] <= current_time, user is online
    # Initially all users are online, so offline_until is 0 (or -1, any value <= 1)
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp; for same timestamp, OFFLINE before MESSAGE
    def sort_key(event):
        ts = int(event[1])
        if event[0] == "OFFLINE":
            return (ts, 0)
        else:
            return (ts, 1)

    sorted_events = sorted(events, key=sort_key)

    for event in sorted_events:
        event_type = event[0]
        timestamp = int(event[1])

        if event_type == "OFFLINE":
            user_id = int(event[2])
            # User goes offline at timestamp, comes back at timestamp + 60
            offline_until[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            mentions_string = event[2]
            tokens = mentions_string.split()

            for token in tokens:
                if token == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif token == "HERE":
                    for uid in range(numberOfUsers):
                        if offline_until[uid] <= timestamp:
                            mentions[uid] += 1
                else:
                    if token.startswith("id"):
                        uid = int(token[2:])
                        if 0 <= uid < numberOfUsers:
                            mentions[uid] += 1

    return mentions
