    def comb(n_val, k_val):
        if k_val < 0 or k_val > n_val:
            return 0
        if k_val == 0 or k_val == n_val:
            return 1
        if k_val > n_val - k_val:
            k_val = n_val - k_val
        result = 1
        for i in range(k_val):
            result = result * (n_val - i) // (i + 1)
        return result

    total = 0

    for j in range(n):
        val = nums[j]
        left_count = j
        right_count = n - j - 1

        if left_count < 2 or right_count < 2:
            continue

        # Count val's in left and right
        L_val = 0
        for i in range(j):
            if nums[i] == val:
                L_val += 1
        L_other = left_count - L_val

        R_val = 0
        for i in range(j + 1, n):
            if nums[i] == val:
                R_val += 1
        R_other = right_count - R_val

        valid_count = 0

        # For each (a, b) where a = # of val from left, b = # of val from right
        for a in range(min(2, L_val) + 1):
            la = 2 - a
            if la > L_other:
                continue
            ways_left = comb(L_val, a) * comb(L_other, la)
            if ways_left == 0:
                continue
            for b in range(min(2, R_val) + 1):
                ra = 2 - b
                if ra > R_other:
                    continue
                ways_right = comb(R_val, b) * comb(R_other, ra)
                if ways_right == 0:
                    continue

                total_val = 1 + a + b
                total_other = 4 - a - b

                if total_val >= 3:
                    valid_count = (valid_count + ways_left * ways_right) % MOD
                elif total_val == 2:
                    # total_other = 3, all 3 must be distinct values
                    la = 2 - a
                    ra = 2 - b

                    left_freq = defaultdict(int)
                    for i in range(j):
                        if nums[i] != val:
                            left_freq[nums[i]] += 1
                    right_freq = defaultdict(int)
