                            sum_sq_excl = sum(c * c for v, c in right_freq.items() if v != v1)
                            ways_right_distinct = (s_excl * s_excl - sum_sq_excl) // 2
                            distinct_ways += cnt1 * ways_right_distinct
                    elif la == 2 and ra == 1:
                        for v3, cnt3 in right_freq.items():
                            s_excl = sum(c for v, c in left_freq.items() if v != v3)
                            sum_sq_excl = sum(c * c for v, c in left_freq.items() if v != v3)
                            ways_left_distinct = (s_excl * s_excl - sum_sq_excl) // 2
                            distinct_ways += cnt3 * ways_left_distinct
                    # la=0,ra=3 or la=3,ra=0 impossible since each side picks at most 2

                    valid_count = (valid_count + ways_left * ways_right * distinct_ways) % MOD
                # total_val == 1 means total_other = 4, impossible since we only pick 2+2=4 others
                # but wait, total_val=1 means a=0,b=0, so la=2, ra=2, total_other=4
                # This case: val appears once (the middle), 2 from left others, 2 from right others
                # Need all 4 others to be distinct from each other and from val.
                # Actually if total_val=1, we need no other value to appear >= 2 times.
                # So all 4 other values must be distinct.
                elif total_val == 1:
