                    left_freq = defaultdict(int)
                    for i in range(j):
                        if nums[i] != val:
                            left_freq[nums[i]] += 1
                    right_freq = defaultdict(int)
                    for i in range(j + 1, n):
                        if nums[i] != val:
                            right_freq[nums[i]] += 1

                    # Need to pick 2 from left and 2 from right, all 4 distinct values, none equal to val (already excluded)
                    # And the 4 values must all be distinct from each other.
                    # Count: sum over pairs (v1,v2) from left and (v3,v4) from right, all 4 distinct.
                    # This is complex. Let's use inclusion-exclusion or just iterate.
                    # Since we need all 4 distinct, and we pick 2 from left, 2 from right:
                    # For left: pick 2 distinct values (v1, v2) with counts c1, c2: c1*c2 ways
                    # For right: pick 2 distinct values (v3, v4) with counts d3, d4, all != v1,v2: d3*d4 ways
                    # Sum over all such combinations.

                    left_items = list(left_freq.items())
                    right_items = list(right_freq.items())

                    distinct_ways = 0
                    for i1 in range(len(left_items)):
                        v1, c1 = left_items[i1]
                        for i2 in range(i1 + 1, len(left_items)):
                            v2, c2 = left_items[i2]
                            # Now pick 2 distinct values from right, both != v1 and v2
                            ways_right = 0
                            for j1 in range(len(right_items)):
                                v3, d3 = right_items[j1]
                                if v3 == v1 or v3 == v2:
                                    continue
                                for j2 in range(j1 + 1, len(right_items)):
                                    v4, d4 = right_items[j2]
                                    if v4 == v1 or v4 == v2:
                                        continue
                                    ways_right += d3 * d4
                            distinct_ways += c1 * c2 * ways_right

                    valid_count = (valid_count + ways_left * ways_right * distinct_ways) % MOD

        total = (total + valid_count) % MOD

    return total
