def longestPalindrome(s: str, t: str):
    n, m = len(s), len(t)

    # dp[i][j] = longest palindrome length in s[i:j+1]
    dp_s = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 1:
                    dp_s[i][j] = 1
                elif length == 2:
                    dp_s[i][j] = 2
                else:
                    dp_s[i][j] = dp_s[i + 1][j - 1] + 2
            else:
                if length > 1:
                    dp_s[i][j] = max(dp_s[i + 1][j], dp_s[i][j - 1])
                # if length == 1, dp_s[i][j] remains 0? No, single char is palindrome of length 1.
                # Wait, my logic above for length==1 sets it to 1. For length>1, if chars don't match, it's max of subproblems.

    # dp_t[i][j] = longest palindrome length in t[i:j+1]
    dp_t = [[0] * m for _ in range(m)]
    for length in range(1, m + 1):
        for i in range(m - length + 1):
            j = i + length - 1
            if t[i] == t[j]:
                if length == 1:
                    dp_t[i][j] = 1
                elif length == 2:
                    dp_t[i][j] = 2
                else:
                    dp_t[i][j] = dp_t[i + 1][j - 1] + 2
            else:
                if length > 1:
                    dp_t[i][j] = max(dp_t[i + 1][j], dp_t[i][j - 1])

    # max_len is the answer
    max_len = 0

    # 1. Palindrome entirely in s
    for i in range(n):
        for j in range(i, n):
            max_len = max(max_len, dp_s[i][j])

    # 2. Palindrome entirely in t
    for i in range(m):
        for j in range(i, m):
            max_len = max(max_len, dp_t[i][j])

    # 3. Palindrome formed by concatenating substring from s and substring from t
    # The substring from s must be a prefix of the chosen part? No, it's any substring.
    # But wait, the problem says "selecting a substring from s ... and a substring from t ... concatenating them in order".
    # This means the resulting string is X + Y, where X is a substring of s and Y is a substring of t.
    # For X+Y to be a palindrome, if X is non-empty and Y is non-empty, the first char of X must match the last char of Y, etc.
    # This implies that the palindrome is formed by taking some prefix-like structure from the end of X matching the start of Y?
    # Actually, let's look at Example 4: s="abcde", t="ecdba".
    # Result "abcba". X="abc" (from s), Y="ba" (from t).
    # "abc" + "ba" = "abcba".
    # Here, X is "abc", Y is "ba".
    # The palindrome is symmetric.
    # Let L be the length of X, R be the length of Y.
    # The string is s[i..j] + t[k..l].
    # This string is a palindrome.
    # This is equivalent to finding the longest palindrome that can be split into two parts, the first part from s, the second from t.
    # However, the split point is not fixed.

    # Alternative approach:
    # Since n, m <= 30, the total length of the concatenated string is at most 60.
    # We can try all possible substrings of s and t?
    # Number of substrings in s is ~450, in t is ~450. Total pairs ~200,000.
    # For each pair, we check if the concatenation is a palindrome.
    # Length of concatenation is up to 60. Checking palindrome is O(60).
    # Total operations: 200,000 * 60 = 12,000,000. This is well within limits.

    # Let's restart with this simpler approach.

    max_len = 0

    # Case 1: Substring only from s (t part is empty)
    for i in range(n):
        for j in range(i, n):
            sub = s[i:j+1]
            if sub == sub[::-1]:
                max_len = max(max_len, len(sub))

    # Case 2: Substring only from t (s part is empty)
    for i in range(m):
        for j in range(i, m):
            sub = t[i:j+1]
            if sub == sub[::-1]:
                max_len = max(max_len, len(sub))

    # Case 3: Non-empty substring from s and non-empty substring from t
    for i in range(n):
        for j in range(i, n):
            sub_s = s[i:j+1]
            for k in range(m):
                for l in range(k, m):
                    sub_t = t[k:l+1]
                    combined = sub_s + sub_t
                    if combined == combined[::-1]:
                        max_len = max(max_len, len(combined))

    return max_len
